DWORD wait_with_sent_messages(HANDLE event,DWORD milliseconds){auto began=GetTickCount64();for(;;){auto elapsed=GetTickCount64()-began;if(elapsed>=milliseconds)return WAIT_TIMEOUT;auto result=MsgWaitForMultipleObjectsEx(1,&event,static_cast<DWORD>(milliseconds-elapsed),QS_SENDMESSAGE,MWMO_INPUTAVAILABLE);if(result!=WAIT_OBJECT_0+1)return result;MSG message{};PeekMessageW(&message,nullptr,0,0,PM_NOREMOVE|PM_QS_SENDMESSAGE);}}
std::wstring guard_mutex_name(){unsigned long long hash=1469598103934665603ULL;for(unsigned char ch:utf8(data_dir().wstring())){hash^=ch;hash*=1099511628211ULL;}return L"Local\\Headroom.SettingsGuard."+std::to_wstring(hash);}

unsigned long long birth(HANDLE p){FILETIME c{},e{},k{},u{};if(!GetProcessTimes(p,&c,&e,&k,&u))return 0;return (static_cast<unsigned long long>(c.dwHighDateTime)<<32)|c.dwLowDateTime;}
std::filesystem::path guard_root(){auto folder=data_dir()/L"settings-guards";std::filesystem::create_directories(folder);return folder;}
Records read_record(const std::filesystem::path& path){auto data=read_shared_file(path);if(data.empty())throw std::runtime_error("Settings recovery record is unavailable");return decode(data);}

int integer(const std::string& text,int minimum,int maximum){size_t used=0;int value=std::stoi(text,&used);if(used!=text.size()||value<minimum||value>maximum)throw std::runtime_error("Invalid device profile number");return value;}
DEVMODEW mode_value(const DisplayMode& mode){DEVMODEW result{};result.dmSize=sizeof result;result.dmFields=DM_PELSWIDTH|DM_PELSHEIGHT|DM_BITSPERPEL|DM_DISPLAYFREQUENCY|DM_POSITION|DM_DISPLAYORIENTATION|DM_DISPLAYFLAGS;result.dmPelsWidth=mode.width;result.dmPelsHeight=mode.height;result.dmBitsPerPel=mode.bits;result.dmDisplayFrequency=mode.hz;result.dmPosition={mode.x,mode.y};result.dmDisplayOrientation=mode.orientation;result.dmDisplayFlags=mode.flags;return result;}
std::string animations(){ANIMATIONINFO animation{sizeof animation,0};BOOL client=FALSE,menu=FALSE;if(!SystemParametersInfoW(SPI_GETANIMATION,sizeof animation,&animation,0)||!SystemParametersInfoW(SPI_GETCLIENTAREAANIMATION,0,&client,0)||!SystemParametersInfoW(SPI_GETMENUANIMATION,0,&menu,0))throw std::runtime_error("Cannot read Windows animation settings");return std::to_string(animation.iMinAnimate?1:0)+std::to_string(client?1:0)+std::to_string(menu?1:0);}
int animation_index(const std::string& type){if(type=="animation-min")return 0;if(type=="animation-client")return 1;if(type=="animation-menu")return 2;throw std::runtime_error("Unknown animation setting");}
void set_animation(const std::string& type,const std::string& value){if(value!="0"&&value!="1")throw std::runtime_error("Invalid animation recovery state");int index=animation_index(type);BOOL enabled=value=="1";if(index==0){ANIMATIONINFO animation{sizeof animation,enabled};if(!SystemParametersInfoW(SPI_SETANIMATION,sizeof animation,&animation,SPIF_SENDCHANGE))throw std::runtime_error("Cannot apply minimize animation setting");}else if(!SystemParametersInfoW(index==1?SPI_SETCLIENTAREAANIMATION:SPI_SETMENUANIMATION,0,reinterpret_cast<void*>(static_cast<INT_PTR>(enabled)),SPIF_SENDCHANGE))throw std::runtime_error("Cannot apply temporary animation setting");}
std::string current(const Row& row){if(row[0]=="power")return active_plan();if(row[0].rfind("animation-",0)==0)return std::string(1,animations()[animation_index(row[0])]);if(row[0]=="display")return encode_displays(current_displays());if(row[0]=="audio")return default_audio(row[4]=="capture",integer(row[5],0,2));throw std::runtime_error("Unknown settings recovery type");}
bool matches_setting(const Row& row,const std::string& a,const std::string& b){return row[0]=="display"?same_displays(a,b):a==b;}
void apply_setting(const Row& row,const std::string& value){if(row[0]=="power")set_plan(value);else if(row[0].rfind("animation-",0)==0)set_animation(row[0],value);else if(row[0]=="display")apply_displays(value);else if(row[0]=="audio")set_default_audio(value,row[4]=="capture",integer(row[5],0,2));else throw std::runtime_error("Unknown settings recovery type");}
bool live_owner(const Row& header){Handle process{OpenProcess(PROCESS_QUERY_LIMITED_INFORMATION|SYNCHRONIZE,FALSE,static_cast<DWORD>(std::stoul(header[3])))};return process.h&&birth(process.h)==std::stoull(header[4])&&WaitForSingleObject(process.h,0)==WAIT_TIMEOUT;}
