    if(file.parent_path()!=guard_root())throw std::runtime_error("Settings recovery left the private folder");auto rows=read_record(file);if(rows.empty()||rows[0].size()!=9||rows[0][0]!="settings-guard"||rows[0][1]!="1")throw std::runtime_error("Invalid settings recovery record");auto& header=rows[0];if(header[2]=="restored"||header[2]=="kept")return "Already finalized";if(owner_check&&live_owner(header))throw std::runtime_error("The owning session is still running");std::ostringstream report;bool conflict=false;
