std::vector<DisplayMode> current_displays(){std::vector<DisplayMode> result;DISPLAY_DEVICEW device{};device.cb=sizeof device;for(DWORD i=0;EnumDisplayDevicesW(nullptr,i,&device,0);++i){if(!(device.StateFlags&DISPLAY_DEVICE_ATTACHED_TO_DESKTOP))continue;DEVMODEW mode{};mode.dmSize=sizeof mode;if(EnumDisplaySettingsW(device.DeviceName,ENUM_CURRENT_SETTINGS,&mode))result.push_back({utf8(device.DeviceName),utf8(device.DeviceString),static_cast<int>(mode.dmPelsWidth),static_cast<int>(mode.dmPelsHeight),static_cast<int>(mode.dmDisplayFrequency),static_cast<int>(mode.dmBitsPerPel),mode.dmPosition.x,mode.dmPosition.y,static_cast<int>(mode.dmDisplayOrientation),mode.dmDisplayFlags});}if(result.empty())throw std::runtime_error("No active display modes are available");return result;}
std::vector<DisplayMode> supported_display_modes(const std::string& device){auto connected=current_displays();auto found=std::find_if(connected.begin(),connected.end(),[&](const DisplayMode& mode){return mode.device==device;});if(found==connected.end())throw std::runtime_error("Display disconnected");std::vector<DisplayMode> result;std::set<std::string> seen;DEVMODEW mode{};mode.dmSize=sizeof mode;for(DWORD n=0;n<4096&&EnumDisplaySettingsW(wide(device).c_str(),n,&mode);++n){if(mode.dmBitsPerPel!=32)continue;auto value=*found;value.width=mode.dmPelsWidth;value.height=mode.dmPelsHeight;value.hz=mode.dmDisplayFrequency;value.bits=mode.dmBitsPerPel;value.flags=mode.dmDisplayFlags;auto key=std::to_string(value.width)+":"+std::to_string(value.height)+":"+std::to_string(value.hz)+":"+std::to_string(value.flags);if(seen.insert(key).second)result.push_back(value);}return result;}
std::string encode_displays(const std::vector<DisplayMode>& modes){Records rows;for(const auto& value:modes)rows.push_back({value.device,std::to_string(value.width),std::to_string(value.height),std::to_string(value.hz),std::to_string(value.bits),std::to_string(value.x),std::to_string(value.y),std::to_string(value.orientation),std::to_string(value.flags)});return encode(rows);}
std::vector<DisplayMode> decode_displays(const std::string& text){auto rows=decode(text);if(rows.empty()||rows.size()>16)throw std::runtime_error("Invalid display layout");std::set<std::string> names;std::vector<DisplayMode> result;for(const auto& row:rows){if(row.size()!=9||row[0].rfind("\\\\.\\DISPLAY",0)!=0||row[0].size()>128||!names.insert(row[0]).second)throw std::runtime_error("Invalid or duplicate display identity");DisplayMode value;value.device=row[0];value.width=integer(row[1],320,16384);value.height=integer(row[2],200,16384);value.hz=integer(row[3],0,1000);value.bits=integer(row[4],32,32);value.x=integer(row[5],-32768,32768);value.y=integer(row[6],-32768,32768);value.orientation=integer(row[7],0,3);value.flags=static_cast<DWORD>(integer(row[8],0,15));result.push_back(value);}return result;}
bool same_displays(const std::string& a,const std::string& b){auto left=decode_displays(a),right=decode_displays(b);auto order=[](const DisplayMode& x,const DisplayMode& y){return x.device<y.device;};std::sort(left.begin(),left.end(),order);std::sort(right.begin(),right.end(),order);return encode_displays(left)==encode_displays(right);}
void apply_displays(const std::string& desired){auto target=decode_displays(desired),before=current_displays();std::set<std::string> names;for(const auto& mode:before)names.insert(mode.device);if(target.size()!=before.size())throw std::runtime_error("Connected display topology changed");for(const auto& mode:target){if(!names.count(mode.device))throw std::runtime_error("A profile display is disconnected");auto value=mode_value(mode);if(ChangeDisplaySettingsExW(wide(mode.device).c_str(),&value,nullptr,CDS_TEST,nullptr)!=DISP_CHANGE_SUCCESSFUL)throw std::runtime_error("Windows rejected an unsupported display mode");}size_t changed=0;try{for(const auto& mode:target){auto value=mode_value(mode);if(ChangeDisplaySettingsExW(wide(mode.device).c_str(),&value,nullptr,0,nullptr)!=DISP_CHANGE_SUCCESSFUL)throw std::runtime_error("Display driver refused the requested mode");++changed;}if(!same_displays(encode_displays(current_displays()),desired))throw std::runtime_error("Display driver did not retain the requested layout");}catch(...){if(changed)for(const auto& mode:before){auto value=mode_value(mode);ChangeDisplaySettingsExW(wide(mode.device).c_str(),&value,nullptr,0,nullptr);}throw;}}
Records device_profiles(const Store& store){Records result;for(const auto& row:store.of("setting"))if(row[1].rfind("device.profile.",0)==0){auto profile=decode(row[2]);if(profile.size()==1&&profile[0].size()==5)result.push_back(profile[0]);}return result;}
DeviceProfile read_device_profile(const Row& row){if(row.size()!=5||row[0]!="1"||row[1].empty()||row[1].size()>160)throw std::runtime_error("Invalid device profile");if(!row[2].empty())decode_displays(row[2]);return {row[1],row[2],row[3],row[4]};}
void save_device_profile(Store& store,const DeviceProfile& profile){Row row{"1",profile.name,profile.displays,profile.playback,profile.microphone};read_device_profile(row);if(profile.displays.empty()&&profile.playback.empty()&&profile.microphone.empty())throw std::runtime_error("Choose a display layout or audio device");store.set("device.profile."+hex(lower(profile.name)),encode({row}));store.save();}
