std::string undo_device_preview(const std::filesystem::path& record){auto file=std::filesystem::weakly_canonical(record);if(file.parent_path()!=guard_root())throw std::runtime_error("Device recovery record is outside this user's private folder");Handle owner{CreateMutexW(nullptr,FALSE,guard_mutex_name().c_str())};if(!owner.h)throw std::runtime_error(error());auto lock=WaitForSingleObject(owner.h,0);if(lock!=WAIT_OBJECT_0&&lock!=WAIT_ABANDONED)throw std::runtime_error("Another temporary settings profile is active");struct Unlock{HANDLE h;~Unlock(){ReleaseMutex(h);}} unlock{owner.h};auto rows=read_record(file);if(rows.empty()||rows[0].size()!=9||rows[0][0]!="settings-guard"||rows[0][2]!="kept")throw std::runtime_error("No confirmed device preview remains to revert");rows[0][2]="applied";atomic_write(file,encode(rows));return restore_record(file,false);}
std::string settings_recovery(bool restore){std::ostringstream out;out<<"TEMPORARY DEVICE / POWER / ANIMATION RECOVERY\n";unsigned pending=0;for(const auto& file:std::filesystem::directory_iterator(guard_root())){if(file.path().extension()!=L".dat")continue;try{auto rows=read_record(file.path());if(rows.empty()||rows[0].size()!=9||rows[0][2]=="restored"||rows[0][2]=="kept")continue;++pending;out<<file.path().filename().string()<<" / "<<rows[0][2]<<"\n";if(restore)out<<restore_record(file.path(),true)<<"\n";}catch(const std::exception& e){out<<"Record preserved: "<<e.what()<<"\n";}}if(!pending)out<<"No pending device/settings recovery records.\n";return out.str();}
